def to_ini(d):
    out = []
    for sec, body in d.items():
        out.append("[" + str(sec) + "]")
        for k, v in body.items():
            if v is None:
                s = ""
            elif isinstance(v, bool):
                s = "true" if v else "false"
            else:
                s = str(v)
            out.append(str(k) + "=" + s)
    return ("\n".join(out) + "\n") if out else ""

